    Brightness? brightness,
    Color? primary,
    Color? onPrimary,
    Color? primaryContainer,
    Color? onPrimaryContainer,
    Color? secondary,
    Color? onSecondary,
    Color? secondaryContainer,
    Color? onSecondaryContainer,
    Color? tertiary,
    Color? onTertiary,
    Color? tertiaryContainer,
    Color? onTertiaryContainer,
    Color? background,
    Color? surface,
    Color? surfaceElevated,
    Color? fill,
    Color? inverseSurface,
    Color? onInverseSurface,
    Color? text,
    Color? textSecondary,
    Color? textTertiary,
    Color? textDisabled,
    Color? link,
    Color? border,
    Color? divider,
    Color? focus,
    Color? error,
    Color? onError,
    Color? errorContainer,
    Color? onErrorContainer,
    Color? success,
    Color? onSuccess,
    Color? successContainer,
    Color? onSuccessContainer,
    Color? warning,
    Color? onWarning,
    Color? warningContainer,
    Color? onWarningContainer,
    Color? info,
    Color? onInfo,
    Color? infoContainer,
    Color? onInfoContainer,
    Color? overlay,
    Color? selection,
    Color? skeleton,
    Color? skeletonHighlight,
    Color? scrim,
    Color? shadow,
    DarkStyle? style,
  }) => ResolvedPalette.fromList(
    brightness ?? this.brightness,
    [
      primary ?? this.primary,
      onPrimary ?? this.onPrimary,
      primaryContainer ?? this.primaryContainer,
      onPrimaryContainer ?? this.onPrimaryContainer,
      secondary ?? this.secondary,
      onSecondary ?? this.onSecondary,
      secondaryContainer ?? this.secondaryContainer,
      onSecondaryContainer ?? this.onSecondaryContainer,
      tertiary ?? this.tertiary,
      onTertiary ?? this.onTertiary,
      tertiaryContainer ?? this.tertiaryContainer,
      onTertiaryContainer ?? this.onTertiaryContainer,
      background ?? this.background,
      surface ?? this.surface,
      surfaceElevated ?? this.surfaceElevated,
      fill ?? this.fill,
      inverseSurface ?? this.inverseSurface,
      onInverseSurface ?? this.onInverseSurface,
      text ?? this.text,
      textSecondary ?? this.textSecondary,
      textTertiary ?? this.textTertiary,
      textDisabled ?? this.textDisabled,
      link ?? this.link,
      border ?? this.border,
      divider ?? this.divider,
      focus ?? this.focus,
      error ?? this.error,
      onError ?? this.onError,
      errorContainer ?? this.errorContainer,
      onErrorContainer ?? this.onErrorContainer,
      success ?? this.success,
      onSuccess ?? this.onSuccess,
      successContainer ?? this.successContainer,
      onSuccessContainer ?? this.onSuccessContainer,
      warning ?? this.warning,
      onWarning ?? this.onWarning,
      warningContainer ?? this.warningContainer,
      onWarningContainer ?? this.onWarningContainer,
      info ?? this.info,
      onInfo ?? this.onInfo,
      infoContainer ?? this.infoContainer,
      onInfoContainer ?? this.onInfoContainer,
      overlay ?? this.overlay,
      selection ?? this.selection,
      skeleton ?? this.skeleton,
      skeletonHighlight ?? this.skeletonHighlight,
      scrim ?? this.scrim,
      shadow ?? this.shadow,
